'use strict';
/** 3D 場景的鏡頭關鍵幀內插（spec §5.8；經典腳本，全域 CAMERA3D，串在場景插件前面送進沙盒，Vitest 用 vm 測）。
 *  關鍵幀 {t（相對區段開頭的秒數）, position [x,y,z], target [x,y,z]（看向的點）, fov（垂直視角，度）}；
 *  兩個關鍵幀之間用 smoothstep（慢進慢出），第一個之前停在第一個、最後一個之後停在最後一個。 */
const CAMERA3D = (() => {
  /** 慢進慢出 */
  const smooth = (u) => { const x = Math.min(1, Math.max(0, u)); return x * x * (3 - 2 * x); };
  /** 向量線性內插 */
  const mix = (a, b, k) => a.map((v, i) => v + (b[i] - v) * k);

  /** 時間 t 的鏡頭；沒有關鍵幀回 null */
  function cameraAt(keys, t) {
    if (!keys || !keys.length) return null;
    const ks = [...keys].sort((a, b) => a.t - b.t);
    const pick = (k) => ({ position: [...k.position], target: [...k.target], fov: k.fov });
    if (t <= ks[0].t) return pick(ks[0]);
    for (let i = 1; i < ks.length; i++) {
      const a = ks[i - 1], b = ks[i];
      if (t < b.t) {
        const k = smooth((t - a.t) / (b.t - a.t));
        return { position: mix(a.position, b.position, k), target: mix(a.target, b.target, k), fov: a.fov + (b.fov - a.fov) * k };
      }
    }
    return pick(ks[ks.length - 1]);
  }

  return { cameraAt };
})();

;
// 內建 3D 範本「Screen in a scene」（spec §5.8）：螢幕播當格畫面（V1），放在三種程式畫的場景裡：
//   desk（木紋桌上的螢幕）、classroom（教室黑板，影片就是板面）、studio（攝影棚，螢幕立在架上、聚光）。
// 場景全部用程式畫（沒有外部素材，開發者 2026-10-27 決定）；桌上螢幕移植自 spikes/export-bench/src/scene3d.ts。
// 三個場景的螢幕位置、大小相同，運鏡共用。頭尾接回滿版：區段開頭與結尾鏡頭正對螢幕、螢幕剛好填滿畫面。
// 鏡頭：有鏡頭關鍵幀（env.params.cameraKeys，前面串了 cameraPath.js 的 CAMERA3D）就照關鍵幀走，否則用 motion 預設運鏡。
// 參數：scene、motion（reveal 拉遠再推回／push 慢慢推近／orbit 繞半圈）、tilt（螢幕後仰度數）、ramp（頭尾過場秒數）。
/* global CAMERA3D */

/** 畫面只由 t 決定（跳格不必從頭推） */
const pure = true;

/** 螢幕寬高（場景單位）與中心高度 */
const SCREEN_W = 4.0;
const SCREEN_H = SCREEN_W * 9 / 16;
const CENTER_Y = 1.25;

/** 場景物件（setup 建、update 用） */
const S = {};

/** 木紋程序貼圖：幾個頻率的正弦疊成年輪＋固定偽雜訊（每次都一樣）；tone 調深淺 */
function woodTexture(THREE, tone) {
  const size = 256;
  const data = new Uint8Array(size * size * 4);
  for (let y = 0; y < size; y++) {
    const ring = Math.sin(y * 0.21) * 0.5 + Math.sin(y * 0.047 + 1.3) * 0.35 + Math.sin(y * 0.9) * 0.15;
    for (let x = 0; x < size; x++) {
      const noise = ((x * 7919 + y * 104729) % 97) / 97 - 0.5;
      const k = (0.62 + ring * 0.16 + noise * 0.05) * tone;
      const i = (y * size + x) * 4;
      data[i] = Math.min(255, 168 * k + 20);
      data[i + 1] = Math.min(255, 112 * k + 12);
      data[i + 2] = Math.min(255, 66 * k + 8);
      data[i + 3] = 255;
    }
  }
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(4, 3);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.generateMipmaps = true;
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.needsUpdate = true;
  return tex;
}

/** 垂直漸層貼圖（攝影棚背景） */
function gradientTexture(THREE, top, bottom) {
  const c = new OffscreenCanvas(4, 256);
  const g = c.getContext('2d');
  const grad = g.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, top);
  grad.addColorStop(1, bottom);
  g.fillStyle = grad;
  g.fillRect(0, 0, 4, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

/** 木紋桌：桌面、螢幕邊框與底座、桌上的方塊和杯子 */
function buildDesk(THREE, scene, group) {
  scene.background = new THREE.Color(0x1a1410);
  const desk = new THREE.Mesh(new THREE.PlaneGeometry(26, 16), new THREE.MeshStandardMaterial({ map: woodTexture(THREE, 1), roughness: 0.75 }));
  desk.rotation.x = -Math.PI / 2;
  scene.add(desk);
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.22, SCREEN_H + 0.22, 0.1), new THREE.MeshStandardMaterial({ color: 0x15171c, roughness: 0.4, metalness: 0.3 })));
  const stand = new THREE.MeshStandardMaterial({ color: 0x2a2d35, roughness: 0.5, metalness: 0.4 });
  const neck = new THREE.Mesh(new THREE.BoxGeometry(0.35, 1.2, 0.12), stand);
  neck.position.set(0, -0.95, -0.1);
  group.add(neck);
  const base = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.06, 1.0), stand);
  base.position.set(0, 0.03, 0.15);
  scene.add(base);
  const block = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.5, 0.7), new THREE.MeshStandardMaterial({ color: 0x3b7ddd, roughness: 0.6 }));
  block.position.set(-3.2, 0.25, 1.2);
  block.rotation.y = 0.5;
  scene.add(block);
  const cup = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.24, 0.6, 32), new THREE.MeshStandardMaterial({ color: 0xe9e6df, roughness: 0.3 }));
  cup.position.set(3.1, 0.3, 1.6);
  scene.add(cup);
}

/** 教室：牆、木地板、黑板邊框與粉筆槽（影片就是板面）、講桌 */
function buildClassroom(THREE, scene, group) {
  scene.background = new THREE.Color(0xd9d2c3);
  const wall = new THREE.Mesh(new THREE.PlaneGeometry(30, 12), new THREE.MeshStandardMaterial({ color: 0xe8e0cf, roughness: 0.95 }));
  wall.position.set(0, 4, -0.3);
  scene.add(wall);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(30, 16), new THREE.MeshStandardMaterial({ map: woodTexture(THREE, 0.75), roughness: 0.8 }));
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.6;
  scene.add(floor);
  // 黑板木框（比螢幕大一圈）與粉筆槽
  const frame = new THREE.MeshStandardMaterial({ color: 0x6b4a2b, roughness: 0.7 });
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.5, SCREEN_H + 0.5, 0.08), frame));
  const tray = new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.5, 0.08, 0.25), frame);
  tray.position.set(0, -SCREEN_H / 2 - 0.28, 0.12);
  group.add(tray);
  for (let i = 0; i < 3; i++) {
    const chalk = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 0.22, 10), new THREE.MeshStandardMaterial({ color: [0xffffff, 0xf7e27a, 0xf2a3b3][i], roughness: 0.9 }));
    chalk.rotation.z = Math.PI / 2;
    chalk.position.set(-1.2 + i * 0.35, -SCREEN_H / 2 - 0.2, 0.15);
    group.add(chalk);
  }
  // 講桌
  const lectern = new THREE.Mesh(new THREE.BoxGeometry(1.6, 1.1, 0.8), frame);
  lectern.position.set(2.8, -0.05, 2.2);
  scene.add(lectern);
}

/** 攝影棚：漸層背幕、地面、螢幕立架、兩盞聚光的光錐 */
function buildStudio(THREE, scene, group) {
  scene.background = new THREE.Color(0x101318);
  const backdrop = new THREE.Mesh(new THREE.PlaneGeometry(40, 16), new THREE.MeshBasicMaterial({ map: gradientTexture(THREE, '#2c3240', '#0d0f14') }));
  backdrop.position.set(0, 4, -6);
  scene.add(backdrop);
  const floor = new THREE.Mesh(new THREE.PlaneGeometry(40, 20), new THREE.MeshStandardMaterial({ color: 0x1b1f27, roughness: 0.35, metalness: 0.2 }));
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -0.6;
  scene.add(floor);
  group.add(new THREE.Mesh(new THREE.BoxGeometry(SCREEN_W + 0.14, SCREEN_H + 0.14, 0.08), new THREE.MeshStandardMaterial({ color: 0x0b0c10, roughness: 0.3, metalness: 0.5 })));
  // 立架：從螢幕下緣到地面（沒有環境貼圖，金屬感調低免得暗掉），底下一塊圓底座
  const steel = new THREE.MeshStandardMaterial({ color: 0x9aa3b2, metalness: 0.3, roughness: 0.4 });
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 1.8, 16), steel);
  pole.position.set(0, -0.6 + 0.9 - CENTER_Y, -0.1);
  group.add(pole);
  const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.7, 0.05, 32), steel);
  foot.position.set(0, -0.575, 0);
  scene.add(foot);
  for (const x of [-4.5, 4.5]) {
    const cone = new THREE.Mesh(new THREE.ConeGeometry(1.8, 7, 32, 1, true), new THREE.MeshBasicMaterial({ color: 0xfff3d6, transparent: true, opacity: 0.07, side: THREE.DoubleSide, depthWrite: false }));
    cone.position.set(x, 3, -1);
    cone.rotation.z = x < 0 ? -0.35 : 0.35;
    scene.add(cone);
  }
}

/** 建場景 */
function setup(THREE, scene, camera, env) {
  scene.add(new THREE.AmbientLight(0xffffff, 1.1));
  const sun = new THREE.DirectionalLight(0xfff1dd, 2.2);
  sun.position.set(-4, 8, 6);
  scene.add(sun);

  const tilt = -(env.params.tilt ?? 7) * Math.PI / 180;
  const group = new THREE.Group();
  group.position.set(0, CENTER_Y, 0);
  group.rotation.x = tilt;
  scene.add(group);
  const kind = env.params.scene || 'desk';
  if (kind === 'classroom') buildClassroom(THREE, scene, group);
  else if (kind === 'studio') buildStudio(THREE, scene, group);
  else buildDesk(THREE, scene, group);
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(SCREEN_W, SCREEN_H), env.frameMaterial());
  screen.position.z = 0.056;
  group.add(screen);

  // 滿版位置：正對螢幕、沿螢幕法線退到剛好填滿畫面的距離（畫面比螢幕寬時以高度為準）
  S.fov0 = camera.fov;
  const fov = camera.fov * Math.PI / 180;
  const aspect = env.width / env.height;
  const dist = Math.max(SCREEN_H / 2, SCREEN_W / 2 / aspect) / Math.tan(fov / 2) + 0.056;
  const normal = new THREE.Vector3(0, 0, 1).applyAxisAngle(new THREE.Vector3(1, 0, 0), tilt);
  const center = new THREE.Vector3(0, CENTER_Y, 0).add(normal.clone().multiplyScalar(0.056));
  S.THREE = THREE;
  S.camera = camera;
  S.flat = { pos: center.clone().add(normal.clone().multiplyScalar(dist - 0.056)), look: center.clone(), up: new THREE.Vector3(0, 1, 0).applyAxisAngle(new THREE.Vector3(1, 0, 0), tilt), fov: camera.fov };
}

/** 平滑（頭尾慢、中間快） */
function smooth(u) {
  const x = Math.min(1, Math.max(0, u));
  return x * x * (3 - 2 * x);
}

/** 預設運鏡的中間段（u：0～1） */
function presetCamera(THREE, motion, u) {
  const look = new THREE.Vector3(0, CENTER_Y * 0.8, 0);
  if (motion === 'orbit') {
    const a = -0.8 + u * 1.6;
    return { pos: new THREE.Vector3(Math.sin(a) * 9, 4.2, Math.cos(a) * 9), look, fov: S.fov0 };
  }
  if (motion === 'push') return { pos: new THREE.Vector3(0.8 - u * 0.8, 3.6 - u * 1.2, 10 - u * 3.5), look, fov: S.fov0 };
  return { pos: new THREE.Vector3(-1.2 + u * 2.4, 4.4, 9.5), look, fov: S.fov0 };
}

/** 中間段在時間 t 的鏡頭：有關鍵幀照關鍵幀，否則預設運鏡 */
function middleCamera(THREE, env, t, ramp) {
  const keys = env.params.cameraKeys;
  if (keys && keys.length) {
    const c = CAMERA3D.cameraAt(keys, t);
    return { pos: new THREE.Vector3(...c.position), look: new THREE.Vector3(...c.target), fov: c.fov };
  }
  const L = env.duration;
  return presetCamera(THREE, env.params.motion || 'reveal', L > 2 * ramp ? (t - ramp) / (L - 2 * ramp) : 0.5);
}

/** 每格更新鏡頭：頭尾在滿版與中間段之間過場 */
function update(t, env) {
  const THREE = S.THREE;
  const camera = S.camera;
  const L = env.duration;
  const ramp = Math.min(env.params.ramp ?? 1.2, L / 3);
  let k = 1;
  let target;
  if (t < ramp) { k = smooth(t / ramp); target = middleCamera(THREE, env, ramp, ramp); }
  else if (t > L - ramp) { k = smooth((L - t) / ramp); target = middleCamera(THREE, env, L - ramp, ramp); }
  else target = middleCamera(THREE, env, t, ramp);
  camera.position.copy(S.flat.pos).lerp(target.pos, k);
  camera.up.copy(S.flat.up).lerp(new THREE.Vector3(0, 1, 0), k).normalize();
  camera.lookAt(S.flat.look.clone().lerp(target.look, k));
  camera.fov = S.flat.fov + (target.fov - S.flat.fov) * k;
  camera.updateProjectionMatrix();
}

function draw(g, t, p, env) {
  const b = env.box, pad = p.padding, u = clamp(t / p.inDur, 0, 1), fade = clamp((env.duration - t) / 0.25, 0, 1);
  const w = b.w + pad * 2, h = b.h + pad * 2;
  let s = 1, a = fade, prog = 1;
  if (p.motion === 'draw') prog = ease.outCubic(u);
  else if (p.motion === 'pop') s = ease.outBack(u);
  else a = a * ease.outQuad(u);
  if (p.pulse && u >= 1) s = s * (1 + Math.sin((t - p.inDur) * 6) * 0.025);
  if (s <= 0.001) return;
  g.save(); g.alpha(a); g.translate(b.x + b.w / 2, b.y + b.h / 2); g.scale(s, s);
  if (p.shadow) g.glow({color: '#00000080', blur: 12});
  g.begin(); g.roundRect(-w / 2, -h / 2, w, h, p.radius);
  g.stroke({color: p.color, width: p.width, progress: prog});
  g.restore();
}

'use strict';
/** 平面轉 3D 共用數學（純函式：沒有 DOM、沒有全域狀態，node 可直接載入測試）。
 *  與 backend/plane3d_math.py 對稱實作，scripts/plane3d-math-parity.js 比對兩邊輸出；改一邊一定要同步改另一邊，
 *  否則工作台預覽、MP4 與 XML 的板子位置會對不上。設計見 docs/superpowers/specs/2026-10-25-plane3d-design.md §2、§3。
 *  ffmpeg 運算式只有引擎需要，這裡沒有。
 *
 *  座標約定：姿勢 pose＝{rx, ry, rz, size, px, py}，角度用度；size＝正對鏡頭時板子寬佔畫面寬的比例（1＝滿版）；
 *  px／py 以畫面寬、高為 1。旋轉順序 Rz → Rx → Ry，四角順序左上、右上、左下、右下。 */
const PLANE3D = (() => {
  const FOV_DEG = 40;
  const D0 = 1 / Math.tan(FOV_DEG * Math.PI / 180 / 2);   // size=1（滿版）時的距離
  const PAD = 4;              // 輸出時來源外圍的透明邊（px）；預覽不用
  const EDGE_RAMP = 0.6;      // 頭尾接回平面的秒數（區間太短時取 L/4）
  const MAX_KEYS = 20;
  const MIN_Z = 0.3 * D0;     // 任一角離鏡頭的最近距離
  const MAX_SPREAD = 4;       // 投影點離畫面中心最多幾倍畫面寬／高
  const SHADOW_DY = 0.026;   // 陰影往下偏移（以畫面高為 1）；預覽與輸出共用
  const SHADOW_SIGMA = 0.02; // 陰影模糊的標準差（以畫面高為 1）
  const FLAT = {rx: 0, ry: 0, rz: 0, size: 1, px: 0, py: 0};
  const PARAMS = ['rz', 'rx', 'ry', 'size', 'px', 'py'];
  const RANGES = {rx: [-80, 80], ry: [-80, 80], rz: [-180, 180], size: [0.15, 1.5], px: [-1, 1], py: [-1, 1]};
  const FLOAT_RANGES = {rx: [0, 15], ry: [0, 15], period: [1, 10]};
  const EASES = ['inOut', 'linear', 'in', 'out'];
  const rad = (deg) => deg * Math.PI / 180;

  /** 緩動：inOut＝easeInOutCubic、in＝u³、out＝1−(1−u)³、linear。u 夾在 0～1。 */
  function ease(kind, u) {
    u = Math.min(1, Math.max(0, u));
    if (kind === 'linear') return u;
    if (kind === 'in') return u ** 3;
    if (kind === 'out') return 1 - (1 - u) ** 3;
    return u < 0.5 ? 4 * u ** 3 : 1 - (2 - 2 * u) ** 3 / 2;
  }

  /** 頭尾接回平面的秒數。 */
  const edgeRamp = (L) => Math.min(EDGE_RAMP, L / 4);

  /** 每個使用者關鍵幀的剪後時間（秒，相對區段開頭）；edges 開時 ramp 加在使用者關鍵幀外面。不是嚴格遞增時丟錯。 */
  function keyTimes(effect, L) {
    const r = effect.edges ? edgeRamp(L) : 0;
    const out = effect.keys.map((k) => Math.min(L - r, Math.max(r, (k.anchor || 'start') === 'start' ? r + k.t : L - r - k.t)));
    for (let i = 1; i < out.length; i++) if (out[i] <= out[i - 1]) throw new Error('plane3d: key times not increasing');
    return out;
  }

  /** 實際使用的關鍵幀時間：keyTimes 不遞增時（區間剪到太短）照順序平均排在 [r, L−r]。 */
  function resolvedTimes(effect, L) {
    try { return keyTimes(effect, L); } catch (err) {
      const r = effect.edges ? edgeRamp(L) : 0, n = effect.keys.length;
      return n > 1 ? effect.keys.map((_, i) => r + (L - 2 * r) * i / (n - 1)) : [r];
    }
  }

  /** 關鍵幀路徑可不可以用：每個點與相鄰兩點之間每 0.1 取樣（有 float 再加四個擺動極端），全部 poseValid。 */
  function pathValid(keys, float, w, h) {
    const poses = keys.map((k) => Object.fromEntries(PARAMS.map((p) => [p, k[p]])));
    let samples = [...poses];
    for (let i = 1; i < poses.length; i++) {
      const a = poses[i - 1], b = poses[i];
      for (let j = 1; j < 10; j++) samples.push(Object.fromEntries(PARAMS.map((p) => [p, a[p] + (b[p] - a[p]) * j / 10])));
    }
    if (float) samples = samples.flatMap((s) => [-1, 1].flatMap((sx) => [-1, 1].map((sy) => ({...s, rx: s.rx + sx * float.rx, ry: s.ry + sy * float.ry}))));
    return samples.every((s) => poseValid(s, w, h));
  }

  /** 內插節點 [{T, pose, ease}]；edges 開時頭尾各加滿版平面與 ramp（一律 inOut），同一時間點留前面那個。 */
  function nodes(effect, L) {
    const ts = resolvedTimes(effect, L);
    let ns = effect.keys.map((k, i) => ({T: ts[i], pose: Object.fromEntries(PARAMS.map((p) => [p, k[p]])), ease: k.ease || 'inOut'}));
    const r = effect.edges ? edgeRamp(L) : 0;
    if (effect.edges && r > 0) {
      ns = [{T: 0, pose: {...FLAT}, ease: 'inOut'}, {T: r, pose: {...ns[0].pose}, ease: 'inOut'}, ...ns,
        {T: L - r, pose: {...ns[ns.length - 1].pose}, ease: 'inOut'}, {T: L, pose: {...FLAT}, ease: 'inOut'}];
      ns = ns.filter((n, i) => i === 0 || n.T > ns[i - 1].T);
    }
    return ns;
  }

  /** 擺動權重：edges 開時頭尾 ramp 內從 0 漸到 1。 */
  function floatWeight(effect, L, T) {
    if (!effect.edges) return 1;
    const r = edgeRamp(L);
    return r <= 0 ? 1 : ease('inOut', T / r) * ease('inOut', (L - T) / r);
  }

  /** 剪後時間 T 的姿勢：關鍵幀分段內插＋float 擺動。 */
  function poseAt(effect, L, T) {
    const ns = nodes(effect, L);
    let pose = {...ns[ns.length - 1].pose};
    if (T <= ns[0].T) pose = {...ns[0].pose};
    else {
      for (let i = 1; i < ns.length; i++) {
        const a = ns[i - 1], b = ns[i];
        if (T < b.T) {
          const e = ease(b.ease, (T - a.T) / (b.T - a.T));
          pose = Object.fromEntries(PARAMS.map((p) => [p, a.pose[p] + (b.pose[p] - a.pose[p]) * e]));
          break;
        }
      }
    }
    const fl = effect.float;
